package echo

import (
	"crypto/tls"
	"net/http"
	"testing"
)

func TestZZScratchScheme(t *testing.T) {
	cases := []struct {
		name string
		req  *http.Request
		want string
	}{
		{
			name: "invalid X-Forwarded-Proto + X-Forwarded-Protocol https",
			req: &http.Request{Header: http.Header{
				HeaderXForwardedProto:    []string{"invalid"},
				HeaderXForwardedProtocol: []string{"https"},
			}},
			want: "https",
		},
		{
			name: "all forwarded headers invalid -> http",
			req: &http.Request{Header: http.Header{
				HeaderXForwardedProto:    []string{"invalid"},
				HeaderXForwardedProtocol: []string{"invalid"},
				HeaderXForwardedSsl:      []string{"off"},
				HeaderXUrlScheme:         []string{"invalid"},
			}},
			want: "http",
		},
		{
			name: "X-Forwarded-Proto https",
			req:  &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"https"}}},
			want: "https",
		},
		{
			name: "X-Forwarded-Ssl on",
			req:  &http.Request{Header: http.Header{HeaderXForwardedSsl: []string{"on"}}},
			want: "https",
		},
		{
			name: "TLS",
			req:  &http.Request{TLS: &tls.ConnectionState{}},
			want: "https",
		},
		{
			name: "no headers",
			req:  &http.Request{},
			want: "http",
		},
		{
			name: "ftp rejected -> http",
			req:  &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"ftp"}}},
			want: "http",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			c := &context{request: tc.req}
			if got := c.Scheme(); got != tc.want {
				t.Fatalf("Scheme() = %q, want %q", got, tc.want)
			}
		})
	}
}
EOF
