func zzReq(e *Echo, method, path string) (int, string, string) {
	req := httptest.NewRequest(method, path, nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	return rec.Code, strings.Join(rec.Header().Values("X-Mw"), ","), rec.Body.String()
}

func zzLog(t *testing.T, e *Echo, tag string, paths ...string) {
	for _, p := range paths {
